import{_ as d,o as e,c as o,a3 as c}from"./chunks/framework.BlfGB29P.js";const _=JSON.parse('{"title":"Calendar Card Pro configuration","description":"English configuration reference for Calendar Card Pro.","frontmatter":{"title":"Calendar Card Pro configuration","description":"English configuration reference for Calendar Card Pro."},"headers":[],"relativePath":"en/collection/calendar-card-pro/konfiguration.md","filePath":"en/collection/calendar-card-pro/konfiguration.md","lastUpdated":1793123188000}'),r={name:"en/collection/calendar-card-pro/konfiguration.md"};function a(n,t,i,l,s,h){return e(),o("div",null,[...t[0]||(t[0]=[c('<p><a id="calendar-card-pro-configuration"></a><a id="current-focus"></a></p><h1 id="konfigurationsreferenz" tabindex="-1">Configuration reference <a class="header-anchor" href="#konfigurationsreferenz" aria-label="Permalink to &quot;Configuration reference {#konfigurationsreferenz}&quot;">​</a></h1><p>This page maps the option groups of the original reference. The original English reference remains relevant for detailed examples.</p><h2 id="neu-in-v4-1-0" tabindex="-1">New In v4.1.0 <a class="header-anchor" href="#neu-in-v4-1-0" aria-label="Permalink to &quot;New In v4.1.0 {#neu-in-v4-1-0}&quot;">​</a></h2><p>Version <code>4.1.0</code> adds several calendar-related controls:</p><ul><li><code>event_type</code> separates appointments with time from all-day appointments.</li><li><code>filter_field</code> makes <code>blocklist</code> and <code>allowlist</code> work on title, location or description.</li><li><code>replace_field</code>, <code>replace_pattern</code> and <code>replace_with</code> change the displayed text without changing the calendar event itself.</li><li><code>allday_expires_at</code> causes all-day appointments in a calendar to expire earlier in the day.</li><li><code>days_of_week</code> limits a calendar to working days or weekends.</li><li><code>allday_badge</code>, <code>allday_badge_style</code> and <code>allday_badge_color</code> control the new badge display for all-day appointments.</li></ul><h2 id="grundeinstellungen" tabindex="-1">Basic settings <a class="header-anchor" href="#grundeinstellungen" aria-label="Permalink to &quot;Basic settings {#grundeinstellungen}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>option</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>entities</code></td><td>array</td><td>required</td><td>List of calendar entities, optionally with own settings per calendar.</td></tr><tr><td><code>view</code></td><td>string</td><td><code>list</code></td><td>Layout: <code>list</code> for days one below the other, <code>column</code> for days next to one another.</td></tr><tr><td><code>start_date</code></td><td>string</td><td>today</td><td>Start date as <code>YYYY-MM-DD</code> or relative expression like <code>today+7</code>, <code>start_of_week</code>, <code>monday+1w</code>.</td></tr><tr><td><code>days_to_show</code></td><td>number</td><td><code>3</code></td><td>Number of days displayed.</td></tr><tr><td><code>event_type</code></td><td>string</td><td><code>all</code></td><td>Appointment type: <code>all</code>, <code>timed</code> or <code>all_day</code>. Can be set globally or per calendar.</td></tr><tr><td><code>compact_days_to_show</code></td><td>number</td><td>-</td><td>Number of days in compact mode.</td></tr><tr><td><code>compact_events_to_show</code></td><td>number</td><td>-</td><td>Number of appointments in compact mode.</td></tr><tr><td><code>compact_events_complete_days</code></td><td>boolean</td><td><code>false</code></td><td>Shows all appointments for days on which at least one appointment is visible.</td></tr><tr><td><code>show_empty_days</code></td><td>boolean</td><td><code>false</code></td><td>Show days without appointments. In the column view, <code>true</code> by default.</td></tr><tr><td><code>hide_when_empty</code></td><td>boolean</td><td><code>false</code></td><td>Hide card if there are no upcoming appointments.</td></tr><tr><td><code>empty_day_text</code></td><td>string</td><td>localized default</td><td>Custom text for empty days or completely empty cards.</td></tr><tr><td><code>filter_duplicates</code></td><td>boolean</td><td><code>false</code></td><td>Hide duplicate events if title, start, end and location are the same.</td></tr><tr><td><code>split_multiday_events</code></td><td>boolean</td><td><code>false</code></td><td>Show multi-day appointments on each affected day. In the column view, <code>true</code> by default.</td></tr><tr><td><code>language</code></td><td>string</td><td>System, fallback <code>en</code></td><td>Language of the card texts, automatically recognized by Home Assistant.</td></tr><tr><td><code>column</code></td><td>object</td><td>inherits top-level values</td><td>Special display options for <code>view: column</code>.</td></tr></tbody></table><h2 id="nur-fur-die-spaltenansicht" tabindex="-1">For column view only <a class="header-anchor" href="#nur-fur-die-spaltenansicht" aria-label="Permalink to &quot;For column view only {#nur-fur-die-spaltenansicht}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>option</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>column.day_header_gap</code></td><td>string</td><td><code>8px</code></td><td>Distance between day head and first appointment.</td></tr><tr><td><code>column.day_header_separator_width</code></td><td>string</td><td><code>0px</code></td><td>Width of line under day header.</td></tr><tr><td><code>column.day_header_separator_color</code></td><td>string</td><td><code>var(--divider-color)</code></td><td>Color of the line under the day header.</td></tr><tr><td><code>column.min_day_width</code></td><td>number</td><td><code>140</code></td><td>Smallest column width in pixels.</td></tr><tr><td><code>column.min_days_to_show</code></td><td>number</td><td><code>days_to_show</code></td><td>Minimum number of visible columns.</td></tr><tr><td><code>column.min_days_fallback</code></td><td>string</td><td><code>list</code></td><td>Behavior if there is not enough space: <code>list</code> or <code>cramp</code>.</td></tr></tbody></table><h2 id="optionen-ohne-wirkung-in-der-spaltenansicht" tabindex="-1">Options have no effect in the column view <a class="header-anchor" href="#optionen-ohne-wirkung-in-der-spaltenansicht" aria-label="Permalink to &quot;Options have no effect in the column view {#optionen-ohne-wirkung-in-der-spaltenansicht}&quot;">​</a></h2><p>These options remain relevant for the list view, but do not work directly in the column view:</p><p><code>date_vertical_alignment</code>, <code>today_indicator_position</code>, <code>compact_events_to_show</code>, <code>compact_days_to_show</code>, <code>compact_events_complete_days</code>, calendar related <code>split_multiday_events</code>.</p><h2 id="kalenderbezogene-optionen" tabindex="-1">Calendar related options <a class="header-anchor" href="#kalenderbezogene-optionen" aria-label="Permalink to &quot;Calendar related options {#kalenderbezogene-optionen}&quot;">​</a></h2><p>An entry in <code>entities</code> can only be an entity ID or an object with its own settings.</p><table tabindex="0"><thead><tr><th>option</th><th>Description</th></tr></thead><tbody><tr><td><code>entity</code></td><td>Calendar entity, for example <code>calendar.family</code>.</td></tr><tr><td><code>label</code></td><td>Own labeling of the calendar.</td></tr><tr><td><code>label_type</code></td><td>Controls how the caption is read.</td></tr><tr><td><code>color</code></td><td>Calendar color.</td></tr><tr><td><code>accent_color</code></td><td>Accent color for line and optional backgrounds.</td></tr><tr><td><code>label_icon_color</code></td><td>Color for label/icon.</td></tr><tr><td><code>show_time</code></td><td>Show time for this calendar.</td></tr><tr><td><code>show_location</code></td><td>Show location for this calendar.</td></tr><tr><td><code>location_icon</code></td><td>Icon for location information for this calendar, for example <code>mdi:office-building</code>; can override automatic Teams discovery.</td></tr><tr><td><code>show_description</code></td><td>Show description for this calendar.</td></tr><tr><td><code>compact_events_to_show</code></td><td>Compact limit for this calendar.</td></tr><tr><td><code>blocklist</code></td><td>Exclude terms or patterns.</td></tr><tr><td><code>allowlist</code></td><td>Show only matching terms or patterns.</td></tr><tr><td><code>filter_field</code></td><td>Field for <code>blocklist</code>/<code>allowlist</code>: <code>title</code>, <code>location</code> or <code>description</code>.</td></tr><tr><td><code>replace_field</code></td><td>Text replacement field: <code>title</code>, <code>location</code> or <code>description</code>.</td></tr><tr><td><code>replace_pattern</code></td><td>Regex pattern to replace or remove in the selected field.</td></tr><tr><td><code>replace_with</code></td><td>replacement text; without <code>replace_pattern</code> the entire field is replaced.</td></tr><tr><td><code>split_multiday_events</code></td><td>Split multi-day appointments for this calendar.</td></tr><tr><td><code>event_type</code></td><td>Calendar-related appointment type: <code>all</code>, <code>timed</code> or <code>all_day</code>.</td></tr><tr><td><code>allday_expires_at</code></td><td>Time in format <code>HH:MM</code> from which all-day appointments in this calendar are considered past.</td></tr><tr><td><code>days_of_week</code></td><td>Limitation to <code>weekdays</code> or <code>weekends</code>.</td></tr></tbody></table><h2 id="header" tabindex="-1">Headers <a class="header-anchor" href="#header" aria-label="Permalink to &quot;Headers {#header}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>option</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>title</code></td><td>string</td><td>-</td><td>Map title, may contain Home Assistant templates.</td></tr><tr><td><code>title_font_size</code></td><td>string</td><td><code>--calendar-card-font-size-title</code></td><td>Title font size.</td></tr><tr><td><code>title_color</code></td><td>string</td><td><code>--calendar-card-color-title</code></td><td>Title color.</td></tr></tbody></table><h2 id="layout-und-abstande" tabindex="-1">Layout And Spacing <a class="header-anchor" href="#layout-und-abstande" aria-label="Permalink to &quot;Layout And Spacing {#layout-und-abstande}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>option</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>background_color</code></td><td>string</td><td><code>--ha-card-background</code></td><td>Background color of the card.</td></tr><tr><td><code>accent_color</code></td><td>string</td><td><code>#03a9f4</code></td><td>Accent color of the vertical line and optional appointment/all day badges.</td></tr><tr><td><code>vertical_line_width</code></td><td>string</td><td><code>2px</code></td><td>Vertical line width.</td></tr><tr><td><code>day_spacing</code></td><td>string</td><td><code>10px</code></td><td>Distance between days or columns.</td></tr><tr><td><code>event_spacing</code></td><td>string</td><td><code>4px</code></td><td>Inner spacing within an appointment.</td></tr><tr><td><code>additional_card_spacing</code></td><td>string</td><td><code>0px</code></td><td>Additional space at the top/bottom of the card.</td></tr><tr><td><code>height</code></td><td>string</td><td><code>auto</code></td><td>Exact fixed card height.</td></tr><tr><td><code>max_height</code></td><td>string</td><td><code>none</code></td><td>Maximum card height as content grows.</td></tr></tbody></table><h2 id="wochennummern-und-trennlinien" tabindex="-1">Week numbers and dividing lines <a class="header-anchor" href="#wochennummern-und-trennlinien" aria-label="Permalink to &quot;Week numbers and dividing lines {#wochennummern-und-trennlinien}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>option</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>show_week_numbers</code></td><td>string</td><td><code>null</code></td><td>Show week numbers: <code>iso</code>, <code>simple</code> or disabled.</td></tr><tr><td><code>show_current_week_number</code></td><td>boolean</td><td><code>true</code></td><td>Show week number for current/first week.</td></tr><tr><td><code>week_number_font_size</code></td><td>string</td><td><code>12px</code></td><td>Week number font size.</td></tr><tr><td><code>week_number_color</code></td><td>string</td><td><code>var(--primary-text-color)</code></td><td>Week number text color.</td></tr><tr><td><code>week_number_background_color</code></td><td>string</td><td><code>#03a9f450</code></td><td>Week number background color.</td></tr><tr><td><code>first_day_of_week</code></td><td>string</td><td><code>system</code></td><td>Start of week: <code>monday</code>, <code>sunday</code> or <code>system</code>.</td></tr><tr><td><code>day_separator_width</code></td><td>string</td><td><code>0px</code></td><td>dividing line between days.</td></tr><tr><td><code>day_separator_color</code></td><td>string</td><td><code>var(--secondary-text-color)</code></td><td>Tag separator color.</td></tr><tr><td><code>week_separator_width</code></td><td>string</td><td><code>0px</code></td><td>dividing line between weeks.</td></tr><tr><td><code>week_separator_color</code></td><td>string</td><td><code>#03a9f450</code></td><td>Color of the week separator line.</td></tr><tr><td><code>month_separator_width</code></td><td>string</td><td><code>0px</code></td><td>dividing line between months.</td></tr><tr><td><code>month_separator_color</code></td><td>string</td><td><code>var(--primary-text-color)</code></td><td>Color of the month separator line.</td></tr></tbody></table><h2 id="heute-markierung" tabindex="-1">Today marker <a class="header-anchor" href="#heute-markierung" aria-label="Permalink to &quot;Today marker {#heute-markierung}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>option</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>today_indicator</code></td><td>boolean/string</td><td><code>false</code></td><td>Today tag: <code>true</code>, <code>dot</code>, <code>pulse</code>, <code>glow</code>, MDI icon, emoji or image path.</td></tr><tr><td><code>today_indicator_position</code></td><td>string</td><td><code>15% 50%</code></td><td>Position in CSS format.</td></tr><tr><td><code>today_indicator_color</code></td><td>string</td><td><code>#03a9f4</code></td><td>Color of the marking.</td></tr><tr><td><code>today_indicator_size</code></td><td>string</td><td><code>6px</code></td><td>Size of the mark.</td></tr></tbody></table><h2 id="datumsspalte" tabindex="-1">Date column <a class="header-anchor" href="#datumsspalte" aria-label="Permalink to &quot;Date column {#datumsspalte}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>option</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>date_vertical_alignment</code></td><td>string</td><td><code>middle</code></td><td>Vertical alignment: <code>top</code>, <code>middle</code>, <code>bottom</code>.</td></tr><tr><td><code>weekday_font_size</code></td><td>string</td><td><code>14px</code></td><td>Font size of the day of the week.</td></tr><tr><td><code>weekday_color</code></td><td>string</td><td><code>--primary-text-color</code></td><td>Color of the day of the week.</td></tr><tr><td><code>day_font_size</code></td><td>string</td><td><code>26px</code></td><td>Font size of the day number.</td></tr><tr><td><code>day_color</code></td><td>string</td><td><code>--primary-text-color</code></td><td>Color of the day number.</td></tr><tr><td><code>show_month</code></td><td>boolean</td><td><code>true</code></td><td>Show month names.</td></tr><tr><td><code>month_font_size</code></td><td>string</td><td><code>12px</code></td><td>Font size of the month.</td></tr><tr><td><code>month_color</code></td><td>string</td><td><code>--primary-text-color</code></td><td>month color.</td></tr><tr><td><code>weekend_weekday_color</code></td><td>string</td><td>inherits <code>weekday_color</code></td><td>Weekday color on weekends.</td></tr><tr><td><code>weekend_day_color</code></td><td>string</td><td>inherits <code>day_color</code></td><td>Weekend day number color.</td></tr><tr><td><code>weekend_month_color</code></td><td>string</td><td>inherits <code>month_color</code></td><td>Monthly color on the weekend.</td></tr><tr><td><code>today_weekday_color</code></td><td>string</td><td>inherits weekend/standard</td><td>Weekday color for today.</td></tr><tr><td><code>today_day_color</code></td><td>string</td><td>inherits weekend/standard</td><td>Day number color for today.</td></tr><tr><td><code>today_month_color</code></td><td>string</td><td>inherits weekend/standard</td><td>Monthly color for today.</td></tr></tbody></table><h2 id="terminspalte" tabindex="-1">Appointment column <a class="header-anchor" href="#terminspalte" aria-label="Permalink to &quot;Appointment column {#terminspalte}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>option</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>event_background_opacity</code></td><td>number</td><td><code>0</code></td><td>Background opacity for appointments with accent color, 0-100.</td></tr><tr><td><code>event_icon_vertical_alignment</code></td><td>string</td><td><code>top</code></td><td>Vertical icon orientation: <code>top</code>, <code>middle</code>, <code>bottom</code>.</td></tr><tr><td><code>show_past_events</code></td><td>boolean</td><td><code>false</code></td><td>Show appointments that have already ended.</td></tr><tr><td><code>show_countdown</code></td><td>boolean</td><td><code>false</code></td><td>Show countdown to appointment.</td></tr><tr><td><code>show_countdown_allday</code></td><td>boolean</td><td><code>true</code></td><td>Show countdown for all-day appointments too.</td></tr><tr><td><code>show_multiday_allday_time</code></td><td>boolean</td><td><code>true</code></td><td>Show time line for all-day appointments lasting several days; it carries the end date information.</td></tr><tr><td><code>allday_badge</code></td><td>string</td><td><code>off</code></td><td>Full Day Badge Location: <code>off</code>, <code>title</code> or <code>time</code>.</td></tr><tr><td><code>allday_badge_style</code></td><td>string</td><td><code>subtle</code></td><td>Badge style: <code>subtle</code>, <code>outline</code>, <code>tinted</code> or <code>filled</code>.</td></tr><tr><td><code>allday_badge_color</code></td><td>string</td><td><code>accent</code></td><td>Badge color: <code>accent</code>, <code>text</code> or a CSS color.</td></tr><tr><td><code>show_progress_bar</code></td><td>boolean</td><td><code>false</code></td><td>Show progress bar for ongoing appointments.</td></tr><tr><td><code>progress_bar_color</code></td><td>string</td><td><code>var(--secondary-text-color)</code></td><td>Color of the progress bar.</td></tr><tr><td><code>progress_bar_height</code></td><td>string</td><td>calculated</td><td>Height of the progress bar.</td></tr><tr><td><code>progress_bar_width</code></td><td>string</td><td>per layout</td><td>Width of progress bar.</td></tr><tr><td><code>empty_day_color</code></td><td>string</td><td><code>--primary-text-color</code></td><td>Color for text on empty days.</td></tr><tr><td><code>event_font_size</code></td><td>string</td><td><code>14px</code></td><td>Font size of the appointment title.</td></tr><tr><td><code>title_max_lines</code></td><td>number</td><td><code>0</code></td><td>Maximum lines for appointment titles, <code>0</code> = unlimited.</td></tr><tr><td><code>event_color</code></td><td>string</td><td><code>--primary-text-color</code></td><td>Color of the appointment title.</td></tr><tr><td><code>show_time</code></td><td>boolean</td><td><code>true</code></td><td>Show appointment time.</td></tr><tr><td><code>show_single_allday_time</code></td><td>boolean</td><td><code>true</code></td><td>Show time display for individual all-day appointments.</td></tr><tr><td><code>time_24h</code></td><td>boolean</td><td>System</td><td>Use 24-hour format.</td></tr><tr><td><code>time_two_digit_hours</code></td><td>boolean</td><td><code>false</code></td><td>Show hours in double digits.</td></tr><tr><td><code>show_end_time</code></td><td>boolean</td><td><code>true</code></td><td>Show end time.</td></tr><tr><td><code>time_icon_size</code></td><td>string</td><td><code>14px</code></td><td>Clock icon size.</td></tr><tr><td><code>time_font_size</code></td><td>string</td><td><code>12px</code></td><td>Font size of the time.</td></tr><tr><td><code>time_color</code></td><td>string</td><td><code>--secondary-text-color</code></td><td>color of time.</td></tr><tr><td><code>time_max_lines</code></td><td>number</td><td><code>0</code></td><td>Maximum lines for time text.</td></tr><tr><td><code>show_location</code></td><td>boolean</td><td><code>true</code></td><td>Show location.</td></tr><tr><td><code>show_location_allday</code></td><td>boolean</td><td><code>true</code></td><td>Show locations even for all-day appointments if <code>show_location</code> is active.</td></tr><tr><td><code>remove_location_country</code></td><td>boolean/string</td><td><code>false</code></td><td>Remove country names from locations, optionally via regex string.</td></tr><tr><td><code>location_icon_size</code></td><td>string</td><td><code>14px</code></td><td>Location icon size.</td></tr><tr><td><code>location_font_size</code></td><td>string</td><td><code>12px</code></td><td>Font size of the location.</td></tr><tr><td><code>location_color</code></td><td>string</td><td><code>--secondary-text-color</code></td><td>Color of the place.</td></tr><tr><td><code>location_max_lines</code></td><td>number</td><td><code>0</code></td><td>Maximum rows for location.</td></tr><tr><td><code>show_description</code></td><td>boolean</td><td><code>false</code></td><td>Show description.</td></tr><tr><td><code>show_description_allday</code></td><td>boolean</td><td><code>true</code></td><td>Show descriptions even for all-day appointments if <code>show_description</code> is active.</td></tr><tr><td><code>description_icon_size</code></td><td>string</td><td><code>14px</code></td><td>Description icon size.</td></tr><tr><td><code>description_font_size</code></td><td>string</td><td><code>12px</code></td><td>Description font size.</td></tr><tr><td><code>description_color</code></td><td>string</td><td><code>--secondary-text-color</code></td><td>Color of description.</td></tr><tr><td><code>description_max_lines</code></td><td>number</td><td><code>0</code></td><td>Maximum lines for description.</td></tr></tbody></table><h2 id="wetter" tabindex="-1">Weather <a class="header-anchor" href="#wetter" aria-label="Permalink to &quot;Weather {#wetter}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>option</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>weather</code></td><td>object</td><td>-</td><td>Weather configuration.</td></tr><tr><td><code>weather.entity</code></td><td>string</td><td>-</td><td>Weather entity for forecasts.</td></tr><tr><td><code>weather.position</code></td><td>string</td><td><code>date</code></td><td>Position: <code>none</code>, <code>date</code>, <code>event</code>, <code>both</code>.</td></tr><tr><td><code>weather.date</code></td><td>object</td><td>-</td><td>Weather display in the day header.</td></tr><tr><td><code>weather.event</code></td><td>object</td><td>-</td><td>Weather display next to appointments.</td></tr></tbody></table><p><code>weather.date</code> accepted: <code>show_conditions</code>, <code>show_high_temp</code>, <code>show_low_temp</code>, <code>show_uv_index</code>, <code>uv_index_threshold</code>, <code>icon_size</code>, <code>font_size</code>, <code>color</code>.</p><p><code>weather.event</code> accepted: <code>show_conditions</code>, <code>show_temp</code>, <code>show_uv_index</code>, <code>uv_index_threshold</code>, <code>daily_forecast_fallback</code>, <code>max_lines</code>, <code>icon_size</code>, <code>font_size</code>, <code>color</code>.</p><h2 id="aktionen" tabindex="-1">Actions <a class="header-anchor" href="#aktionen" aria-label="Permalink to &quot;Actions {#aktionen}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>option</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>tap_action</code></td><td>object</td><td><code>none</code></td><td>Action when tapping the card.</td></tr><tr><td><code>hold_action</code></td><td>object</td><td><code>none</code></td><td>Action while holding the card.</td></tr></tbody></table><p>Depending on the action, action parameters can be:</p><p><code>action</code>, <code>navigation_path</code>, <code>service</code>, <code>service_data</code>, <code>url_path</code>, <code>open_tab</code>.</p><h2 id="cache-und-aktualisierung" tabindex="-1">Cache And Update <a class="header-anchor" href="#cache-und-aktualisierung" aria-label="Permalink to &quot;Cache And Update {#cache-und-aktualisierung}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>option</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>refresh_interval</code></td><td>number</td><td><code>30</code></td><td>Minutes between data updates.</td></tr><tr><td><code>refresh_on_navigate</code></td><td>boolean</td><td><code>true</code></td><td>Reload when switching between dashboard views.</td></tr></tbody></table>',38)])])}const m=d(r,[["render",a]]);export{_ as __pageData,m as default};
